PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?name ?point ?tz ?tsid ?tslabel WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name .
  FILTER (LCASE(?name) LIKE "%basement%" || LCASE(?name) LIKE "%datacenter_top_zn_6%")
  OPTIONAL { ?point brick:hasParameter ?z ; a brick:Air_Temperature ; ref:hasTimeseriesId ?tsid ; rdfs:label ?tslabel }
}
LIMIT 200

SELECT ?s ?name WHERE {
  ?s rdfs:label ?name .
  FILTER (LCASE(?name) LIKE "%basement%" || LCASE(?name) LIKE "%data_center_top_zn_6%" || LCASE(?name) LIKE "%datacenter_top_zn_6%")
}
LIMIT 50

SELECT ?s ?name WHERE {
  ?s rdfs:label ?name .
  FILTER REGEX(?, "basement|data", "i")
}
LIMIT 50

